import{_ as e,o as r,c as t,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/main/info.md","filePath":"wiki/dev-commit/framework-react/react/main/info.md"}'),i={name:"wiki/dev-commit/framework-react/react/main/info.md"};function o(c,a,n,s,h,d){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><h4 id="документация" tabindex="-1">Документация <a class="header-anchor" href="#документация" aria-label="Permalink to &quot;Документация&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://react.dev/learn" target="_blank" rel="noreferrer">https://react.dev/learn</a><a href="https://react.dev/reference/react" target="_blank" rel="noreferrer">https://react.dev/reference/react</a></p></div><h4 id="прочее" tabindex="-1">Прочее <a class="header-anchor" href="#прочее" aria-label="Permalink to &quot;Прочее&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://max-frontend.gitbook.io/react-course-ru-v2/" target="_blank" rel="noreferrer">https://max-frontend.gitbook.io/react-course-ru-v2/</a><a href="https://github.com/rtivital/react-things" target="_blank" rel="noreferrer">https://github.com/rtivital/react-things</a><a href="https://habr.com/ru/company/ruvds/blog/447134/" target="_blank" rel="noreferrer">https://habr.com/ru/company/ruvds/blog/447134/</a><a href="https://habr.com/ru/company/ruvds/blog/471040/" target="_blank" rel="noreferrer">https://habr.com/ru/company/ruvds/blog/471040/</a></p></div><h2 id="библиотеки" tabindex="-1">Библиотеки <a class="header-anchor" href="#библиотеки" aria-label="Permalink to &quot;Библиотеки&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://github.com/gre/gl-react" target="_blank" rel="noreferrer">https://github.com/gre/gl-react</a><a href="https://github.com/Flipboard/react-canvas" target="_blank" rel="noreferrer">https://github.com/Flipboard/react-canvas</a></p></div><h2 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li><strong>React</strong> (2013 год) - JavaScript-библиотека для разработки пользовательского интерфейса</li><li>Вместо того, чтобы искусственно разделить технологии, помещая разметку и логику в разные файлы, React разделяет ответственность с помощью слабо связанных единиц, называемых «компоненты», которые содержат и разметку и логику (React - это только представление)</li><li>React создает легковесное дерево из JavaScript-объектов для имитации DOM-дерева. Затем он создает из них HTML, который вставляется или добавляется к нужному DOM-элементу, что вызывает перерисовку страницы в браузере</li></ul><h4 id="принципы" tabindex="-1">Принципы <a class="header-anchor" href="#принципы" aria-label="Permalink to &quot;Принципы&quot;">​</a></h4><ol><li>Компоненты (модульный принцип, разделение UI на коллекция компонентов)</li><li>Реактивность</li><li>Реализует только View слой, вместо полного стека MVC</li></ol><h4 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h4><ol><li>Меньшая абстракция по сравнению с Angular и Vue. Можно более детально и точечно использовать силу реакта и писать более эффективные приложения</li><li>React-библиотека. Для создания приложения можно использовать любой набор инструментов, не ограничены рамками фреймворка. Позволяет создавать гибкие решения</li><li>Развитое сообщество</li></ol><h4 id="концепции" tabindex="-1">Концепции <a class="header-anchor" href="#концепции" aria-label="Permalink to &quot;Концепции&quot;">​</a></h4><ol><li>Компоненты</li><li>JSX</li><li>State</li><li>Props</li></ol><h2 id="композиция-вместо-наследования" tabindex="-1">Композиция вместо наследования <a class="header-anchor" href="#композиция-вместо-наследования" aria-label="Permalink to &quot;Композиция вместо наследования&quot;">​</a></h2><ul><li><strong>Композиция</strong> - соединение мальньких или простых частей воедино для создания более крупных частей</li><li>Для переиспользования кода между компонентами рекомендуется использовать композицию вместо наследования</li><li>Если вы хотите переиспользовать не связанную с внешним видом функциональность между компонентами, извлеките её в отдельный JavaScript-модуль. Импортируйте его в компонент и используйте эту функцию, объект или класс, не расширяя их</li></ul>',17)])])}const b=e(i,[["render",o]]);export{m as __pageData,b as default};
